/* verilator lint_off WIDTHTRUNC */
  localparam

// Set VALID_HIGH_BITS < IN_WIDTH to enable the split path.  The caller
  // guarantees whichever of |a|,|b| is the larger operand has 0 in the low
  // (IN_WIDTH-VALID_HIGH_BITS) bits.  Default = IN_WIDTH keeps the original path.
  parameter

// 1'b1: use ext_lzc_cnt & ext_in_zero
  // 1'b1: widen the shift by one bit and apply a small_norm +1 correction
  // intended for USE_EXT_LZC with LZA.
  parameter

// LZA hint: LZC(prod) is either La+Lb or La+Lb+1 depending on whether the
  // MSB carry of the multiply lands. Choosing which requires a dynamic bit-
  // select on the raw product, so we over-predict by +1 and let fp_align's
  // USE_LZA_POSTFIX handle the possible 1-bit overshoot.
  localparam

// M-direction stripmining: vaInfo.va only carries ROWS_PER_CNT = TE/2*COMPRATIO
  // rows per cycle. The pe_array advances cnt to walk through tm rows in
  // ROWS_PER_CNT-sized chunks; this mux picks the correct chunk of vaGroup{Lo,Hi}
  // for the current cnt. Without this slice, every cnt cycle re-multiplied
  // rows 0..ROWS_PER_CNT-1.
  localparam

// assert format is supported

  // The super-format that can hold all input formats
  localparam

// ----------
  // Stage 1: multiplication & Batch-normalization
  // ----------
  // +1 for the pre-round overflow bit, +1 for the sign so vector-lane batch-normalize
  // can carry a possibly-negative max_exp reference without wrap-around.
  localparam

// ----------
  // Stage 2: Add tree + rounding
  // ----------
  // Actually PROD_SIG_BITS+2 should be enough,
  // but let's trust EDA for this optimization since lower bits directly tie to 0.
  localparam

